/**
 * Register Page
 */

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import authService from '../services/authService';
import './Auth.css';

const Register = () => {
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    password: '',
    confirmPassword: '',
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPasswordRequirements, setShowPasswordRequirements] = useState(false);
  const navigate = useNavigate();
  const { register } = useAuth();

  // Password validation rules
  const passwordRequirements = {
    minLength: formData.password.length >= 8,
    hasUppercase: /[A-Z]/.test(formData.password),
    hasLowercase: /[a-z]/.test(formData.password),
    hasNumber: /[0-9]/.test(formData.password),
    hasSpecialChar: /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(formData.password),
  };

  const isPasswordValid = Object.values(passwordRequirements).every(req => req);
  const passwordsMatch = formData.password === formData.confirmPassword && formData.password.length > 0;

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));

    if (name === 'password') {
      setShowPasswordRequirements(true);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    // Client-side validation
    if (!isPasswordValid) {
      setError('Password does not meet all security requirements');
      return;
    }

    if (!passwordsMatch) {
      setError('Passwords do not match');
      return;
    }

    setLoading(true);

    try {
      const data = await authService.register(
        formData.fullName,
        formData.email,
        formData.password,
        formData.confirmPassword
      );
      register(data.user, data.token);
      navigate('/events');
    } catch (err) {
      const errorMsg = err.message || 'Registration failed';
      if (err.errors && Array.isArray(err.errors) && err.errors.length > 0) {
        // Join errors with line breaks for readability
        setError(
          err.errors
            .filter(e => e && typeof e === 'string') // Filter out empty/non-string errors
            .join('\n')
        );
      } else {
        setError(errorMsg);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-page">
      <div className="auth-container">
        <div className="auth-card">
          <h2>Create Account</h2>
          <p className="auth-subtitle">Join our secure event booking platform</p>

          <div className="trust-signal">
            Your data is secure and encrypted
          </div>

          {error && <div className="error-message">{error}</div>}

          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>Full Name</label>
              <input
                type="text"
                name="fullName"
                value={formData.fullName}
                onChange={handleChange}
                placeholder="Enter your full name"
                required
              />
            </div>

            <div className="form-group">
              <label>Email Address</label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                placeholder="Enter your email"
                required
              />
            </div>

            <div className="form-group">
              <label>Password</label>
              <input
                type="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                placeholder="Enter a strong password"
                onFocus={() => setShowPasswordRequirements(true)}
                onBlur={() => {
                  if (formData.password.length === 0) {
                    setShowPasswordRequirements(false);
                  }
                }}
                required
              />
              {showPasswordRequirements && formData.password.length > 0 && (
                <div className="password-requirements">
                  <h4>Password Requirements</h4>
                  <div className={`requirement-item ${passwordRequirements.minLength ? 'met' : 'unmet'}`}>
                    <span className="requirement-icon">{passwordRequirements.minLength ? '✓' : '○'}</span>
                    At least 8 characters
                  </div>
                  <div className={`requirement-item ${passwordRequirements.hasUppercase ? 'met' : 'unmet'}`}>
                    <span className="requirement-icon">{passwordRequirements.hasUppercase ? '✓' : '○'}</span>
                    Uppercase letter (A-Z)
                  </div>
                  <div className={`requirement-item ${passwordRequirements.hasLowercase ? 'met' : 'unmet'}`}>
                    <span className="requirement-icon">{passwordRequirements.hasLowercase ? '✓' : '○'}</span>
                    Lowercase letter (a-z)
                  </div>
                  <div className={`requirement-item ${passwordRequirements.hasNumber ? 'met' : 'unmet'}`}>
                    <span className="requirement-icon">{passwordRequirements.hasNumber ? '✓' : '○'}</span>
                    Number (0-9)
                  </div>
                  <div className={`requirement-item ${passwordRequirements.hasSpecialChar ? 'met' : 'unmet'}`}>
                    <span className="requirement-icon">{passwordRequirements.hasSpecialChar ? '✓' : '○'}</span>
                    Special character (!@#$%^&*)
                  </div>
                </div>
              )}
            </div>

            <div className="form-group">
              <label>Confirm Password</label>
              <input
                type="password"
                name="confirmPassword"
                value={formData.confirmPassword}
                onChange={handleChange}
                placeholder="Confirm your password"
                required
              />
              {formData.confirmPassword && (
                <div className={`helper-text ${passwordsMatch ? 'secure' : 'warning'}`}>
                  {passwordsMatch ? '✓ Passwords match' : '✗ Passwords do not match'}
                </div>
              )}
            </div>

            <button 
              type="submit" 
              className="btn-submit" 
              disabled={loading || !isPasswordValid || !passwordsMatch}
            >
              {loading ? 'Creating Account...' : 'Create Account'}
            </button>
          </form>

          <p className="auth-footer">
            Already have an account? <Link to="/login">Sign in here</Link>
          </p>
          <p className="helper-text" style={{ textAlign: 'center', marginTop: '0.5rem' }}>
            We never share your email with anyone
          </p>
        </div>
      </div>
    </div>
  );
};

export default Register;
